-- Spoken-only variants, never additional /me text.
local _, addon = ...
local texts = addon.localeData.enUS.generalTexts
texts.COMMEND = { gruppe = { "Your efforts deserve public recognition.", "Not every hero needs a medal." }, ziel = { "%s: Not every hero needs a medal.", "%s: Your efforts deserve public recognition." } }
texts.DRINK = { gruppe = { "To good friends and safe journeys home!", "This mug does not have to last until tomorrow." }, ziel = { "%s: This mug does not have to last until tomorrow.", "%s: To good friends and safe journeys home!" } }
texts.GIGGLE = { gruppe = { "I was going to remain serious. Truly.", "The giggle proved stronger than my resolve." }, ziel = { "%s: The giggle proved stronger than my resolve.", "%s: I was going to remain serious. Truly." } }
texts.PEON = { gruppe = { "Work, work. Is there never an end to it?", "Who has handed out yet another assignment?" }, ziel = { "%s: Who has handed out yet another assignment?", "%s: Work, work. Is there never an end to it?" } }
texts.SHINDIG = { gruppe = { "Tonight we party until the boots grow tired!", "Let the whole camp hear the music." }, ziel = { "%s: Let the whole camp hear the music.", "%s: Tonight we party until the boots grow tired!" } }
texts.SOB = { gruppe = { "Sometimes remembering simply hurts.", "I need a quiet moment." }, ziel = { "%s: I need a quiet moment.", "%s: Sometimes remembering simply hurts." } }
texts.VICTORY = { gruppe = { "That was a hard-won victory!", "Remember those who stood beside us to earn it." }, ziel = { "%s: Remember those who stood beside us to earn it.", "%s: That was a hard-won victory!" } }
texts.WEEP = { gruppe = { "Some farewells demand many tears.", "Perhaps the world will feel lighter tomorrow." }, ziel = { "%s: Perhaps the world will feel lighter tomorrow.", "%s: Some farewells demand many tears." } }
texts.WELCOME = { gruppe = { "There is still room beside the fire.", "Come in. Good company is always welcome." }, ziel = { "%s: Come in. Good company is always welcome.", "%s: There is still room beside the fire." } }
texts.YES = { gruppe = { "Yes, that is exactly how we'll do it!", "A clear answer saves many detours." }, ziel = { "%s: A clear answer saves many detours.", "%s: Yes, that is exactly how we'll do it!" } }
texts.CAT = { gruppe = { "Meow. One must make oneself understood somehow.", "A little feline wisdom never hurts." }, ziel = { "%s: A little feline wisdom never hurts.", "%s: Meow. One must make oneself understood somehow." } }
texts.CATTY = { gruppe = { "A kind word would apparently be too easy.", "That clawed remark just had to be made." }, ziel = { "%s: That clawed remark just had to be made.", "%s: A kind word would apparently be too easy." } }
texts.CUDDLE = { gruppe = { "Some days simply call for a little closeness.", "A quiet moment can be worth more than gold." }, ziel = { "%s: A quiet moment can be worth more than gold.", "%s: Some days simply call for a little closeness." } }
texts.FART = { gruppe = { "Excuse me, a sudden unexpected breeze.", "I cannot honestly blame the wind for that." }, ziel = { "%s: I cannot honestly blame the wind for that.", "%s: Excuse me, a sudden unexpected breeze." } }
texts.PURR = { gruppe = { "Contentment doesn't always require words.", "I could stay right here for quite a while." }, ziel = { "%s: I could stay right here for quite a while.", "%s: Contentment doesn't always require words." } }
texts.VOLUNTEER = { gruppe = { "I'll take that task. Who will join me?", "If someone must go first, let it be me." }, ziel = { "%s: If someone must go first, let it be me.", "%s: I'll take that task. Who will join me?" } }
texts.WHINE = { gruppe = { "Why does this always happen to me?", "I was hoping for a simpler assignment." }, ziel = { "%s: I was hoping for a simpler assignment.", "%s: Why does this always happen to me?" } }
texts.WHISTLE = { gruppe = { "A merry tune helps on long roads.", "Some tunes appear out of nowhere on the road." }, ziel = { "%s: Some tunes appear out of nowhere on the road.", "%s: A merry tune helps on long roads." } }
texts.WICKED = { gruppe = { "That is a delightfully daring idea.", "I should probably feel a little guilty." }, ziel = { "%s: I should probably feel a little guilty.", "%s: That is a delightfully daring idea." } }
texts.WICKEDLY = { gruppe = { "My plan has edges. Very sharp edges.", "Some choices are surprisingly entertaining." }, ziel = { "%s: Some choices are surprisingly entertaining.", "%s: My plan has edges. Very sharp edges." } }
texts.WORK = { gruppe = { "A good day begins with a task completed.", "Work is calling. Unfortunately it knows my name." }, ziel = { "%s: Work is calling. Unfortunately it knows my name.", "%s: A good day begins with a task completed." } }
texts.WRATH = { gruppe = { "Enough! My mercy ends here.", "Anger without action is merely noise." }, ziel = { "%s: Anger without action is merely noise.", "%s: Enough! My mercy ends here." } }
texts.YAWN = { gruppe = { "I could sleep here for three days.", "A rest would work wonders right now." }, ziel = { "%s: A rest would work wonders right now.", "%s: I could sleep here for three days." } }
texts.BURP = { gruppe = { "The stew has just said its farewell.", "That was louder than I intended." }, ziel = { "%s: That was louder than I intended.", "%s: The stew has just said its farewell." } }
texts.BLOOD = { gruppe = { "That is more blood than I wanted to see.", "A pause and a bandage would be wise." }, ziel = { "%s: A pause and a bandage would be wise.", "%s: That is more blood than I wanted to see." } }
texts.HAIL = { gruppe = { "My salute goes to all who stand watch here.", "Honour to those who keep the road open." }, ziel = { "%s: Honour to those who keep the road open.", "%s: My salute goes to all who stand watch here." } }
texts.RDY = { gruppe = { "Ready! Just say when we begin.", "Everything is set, and the direction is clear." }, ziel = { "%s: Everything is set, and the direction is clear.", "%s: Ready! Just say when we begin." } }
